from collections import Counter

PRICE_PER_GROUP = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    counts = Counter(basket)
    total = 0
    while counts:
        # Form a group from the books with the most copies,
        # up to 5 distinct titles.
        size = min(5, len(counts))
        for _ in range(size):
            book = max(counts, key=counts.get)
            counts[book] -= 1
            if counts[book] == 0:
                del counts[book]
        total += PRICE_PER_GROUP[size]
    return total

