from collections import Counter

PRICE_PER_GROUP = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    counts = Counter(basket)
    total = 0
    while counts:
        # Each round, form one group of up to 5 distinct books, taking a
        # copy from the books that currently have the most copies.
        size = min(5, len(counts))
        # A group of 5 is only optimal when all five distinct books are
        # equally represented. Otherwise a group of 4 leaves a better
        # arrangement (4+4 beats 5+3).
        if size == 5:
            ordered = sorted(counts.values(), reverse=True)
            if ordered[4] < ordered[0]:
                size = 4
        top = sorted(counts, key=counts.get, reverse=True)[:size]
        for book in top:
            counts[book] -= 1
            if counts[book] == 0:
                del counts[book]
        total += PRICE_PER_GROUP[size]
    return total

from collections import Counter
from functools import lru_cache

PRICE_PER_GROUP = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}


def total(basket):
    counts = tuple(sorted(Counter(basket).values(), reverse=True))
    counts = counts + (0,) * (5 - len(counts))

    @lru_cache(maxsize=None)
    def cost(c):
        # c is a descending tuple of the remaining copies of the 5 titles.
        if sum(c) == 0:
            return 0
        distinct = sum(1 for x in c if x > 0)
        best = float("inf")
        for size in range(1, min(5, distinct) + 1):
            # Form a group by taking one copy from each of the
            # `size` titles that currently have the most copies.
            nxt = list(c)
            for i in range(size):
                nxt[i] -= 1
            nxt = tuple(sorted(nxt, reverse=True))
            best = min(best, PRICE_PER_GROUP[size] + cost(nxt))
        return best

    return cost(counts)
